def fit(C, S, lam, mask=None):
    from scipy.optimize import minimize
    p = len(C)
    d = np.arange(p)
    (i, j) = np.triu_indices(p, 1)
    if mask is not None:
        (i, j) = (i[mask], j[mask])

    def unpack(x):
        out = np.diag(x[:p])
        out[i, j] = out[j, i] = x[p:]
        return out

    def f(x):
        q = profile(C, unpack(x))
        if q is None:
            return (100000000.0, np.zeros_like(x))
        (y, g, _) = q
        t = x[p:]
        v = np.hypot(t, 0.012)
        return (y + 2 * lam * np.sum(v - 0.012), np.r_[g[d, d], 2 * (g[i, j] + lam * t / v)])
    x = np.r_[S.diagonal(), S[i, j]]
    S0 = unpack(x)
    gap = np.linalg.eigvalsh(S0)[0]
    if gap < 0.15:
        x[:p] += 0.15 - gap
    opt = minimize(f, x, method='L-BFGS-B', jac=True, options=dict(maxiter=120, ftol=2e-11, gtol=2e-06))
    return unpack(opt.x)
